				for item in v.as_list() {
					all << group_where(item.as_map())!
				}
				conds << device_has_groups_with(...all)
			}
			else {}
		}
	}
	return conds
}

// device_create_input reads the input of `createDevice`.
fn device_create_input(value graphql.Value) !CreateDeviceInput {
	mut input := CreateDeviceInput{}
	for name, v in value.as_map() {
