// resolve_gadget_field resolves the columns of `Gadget`.
fn resolve_gadget_field(_ context.Context, info graphql.FieldInfo, parents []graphql.Source) ![]graphql.Resolved {
	return parents.map(graphql.Resolved(gadget_value((it as GadgetNode).gadget, info.field_name)))
}

fn gadget_value(row models.Gadget, field string) graphql.Value {
	return match field {
		'createdAt' { graphql.Value(row.created_at.format_rfc3339()) }
		'updatedAt' { graphql.Value(row.updated_at.format_rfc3339()) }
		'id' { graphql.Value(row.id.str()) }
		'ownerID' { graphql.Value(row.owner_id.str()) }
		'serialNo' { graphql.Value(string(row.serial_no)) }
		'color' { graphql.Value(row.color.str().to_upper()) }
		'level' { graphql.Value(int(row.level)) }
		'weight' { graphql.Value(int(row.weight)) }
		'parts' { graphql.Value(f64(row.parts)) }
		'big' { graphql.Value(f64(row.big)) }
		'ratio' { graphql.Value(f64(row.ratio)) }
		'rating' {
			if v := row.rating { graphql.Value(f64(v)) } else { graphql.null }
		}
		'score' {
			if v := row.score { graphql.Value(f64(v)) } else { graphql.null }
		}
		'active' {
			if v := row.active { graphql.Value(v) } else { graphql.null }
		}
		'tags' { graphql.parse_json(row.tags) or { graphql.null } }
		else { graphql.null }
	}
}

// graphql_where applies the `where` argument of a `Gadget` list.
fn (q GadgetQuery) graphql_where(args map[string]graphql.Value) !GadgetQuery {
	if w := args['where'] {
		if w is map[string]graphql.Value {
			return q.where(...gadget_where(w)!)
		}
	}
	return q
}

// graphql_args applies the arguments of a `Gadget` list: `where`, `orderBy`,
// and `limit` and `offset`, bounded by `size`.
fn (q GadgetQuery) graphql_args(args map[string]graphql.Value, size graphql.PageSize) !GadgetQuery {
	page := graphql.list_args(args, size)!
	mut next := q.graphql_where(args)!
	if o := args['orderBy'] {
		orders := gadget_order(o, false)!
		if orders.len > 0 {
			next = next.order_by(...orders)
		}
	}
	if limit := page.limit {
		next = next.limit(limit)
	}
	if offset := page.offset {
		next = next.offset(offset)
	}
	return next
}

// gadget_order returns the orders of an `orderBy` of `Gadget`, and with `with_key`,
// the key last, unless it orders by it already.
fn gadget_order(v graphql.Value, with_key bool) ![]load.Order {
	mut items := v.as_list()
	if items.len == 0 && v.as_map().len > 0 {
		items = [v]
	}
	mut orders := []load.Order{}
	mut keyed := false
	for item in items {
		o := item.as_map()
		desc := (o['direction'] or { graphql.null }).as_string() == 'DESC'
		field := (o['field'] or { graphql.null }).as_string()
		match field {
			'CREATED_AT' {
				orders << load.Order{ column: 'Stamps.created_at', desc: desc, typ: 'time.Time' }
			}
			'UPDATED_AT' {
				orders << load.Order{ column: 'Stamps.updated_at', desc: desc, typ: 'time.Time' }
			}
			'ID' {
				orders << load.Order{ column: 'id', desc: desc, typ: 'i64' }
				keyed = true
			}
			'OWNER_ID' {
				orders << load.Order{ column: 'owner_id', desc: desc, typ: 'int' }
			}
			'SERIAL' {
				orders << load.Order{ column: 'serial_no', desc: desc, typ: 'string' }
			}
			'COLOR' {
				orders << load.Order{ column: 'color', desc: desc, typ: 'enum' }
			}
			'LEVEL' {
				orders << load.Order{ column: 'level', desc: desc, typ: 'i8' }
			}
			'WEIGHT' {
				orders << load.Order{ column: 'weight', desc: desc, typ: 'u16' }
			}
			'PARTS' {
				orders << load.Order{ column: 'parts', desc: desc, typ: 'u32' }
			}
			'BIG' {
				orders << load.Order{ column: 'big', desc: desc, typ: 'u64' }
			}
			'RATIO' {
				orders << load.Order{ column: 'ratio', desc: desc, typ: 'f32' }
			}
			'RATING' {
				orders << load.Order{ column: 'rating', desc: desc, typ: '?f64' }
			}
			'SCORE' {
				orders << load.Order{ column: 'score', desc: desc, typ: '?i64' }
			}
			'ACTIVE' {
				orders << load.Order{ column: 'active', desc: desc, typ: '?bool' }
			}
			'LIKERS_COUNT' {
				orders << load.Order{ expr: '(SELECT COUNT(*) FROM "likes" AS "t1" WHERE "t1"."gadget_id" = "t0"."id")', desc: desc, typ: 'int' }
			}
			else { return error('`${field}` is not a GadgetOrderField') }
		}
	}
	if with_key && !keyed {
		// the key breaks ties, in the direction of the last order, as entgql's
		orders << load.Order{
			column: 'id'
			desc:   orders.len > 0 && orders.last().desc
			typ:    'i64'
		}
	}
	return orders
}

// gadget_where returns the conditions of a `GadgetWhereInput`.
fn gadget_where(w map[string]graphql.Value) ![]load.Cond {
	mut conds := []load.Cond{}
	for key, v in w {
		if v is graphql.Null {
			continue
		}
		match key {
			'not' {
				conds << load.not(load.and(...gadget_where(v.as_map())!))
			}
			'and' {
				for item in v.as_list() {
					conds << gadget_where(item.as_map())!
				}
			}
			'or' {
				mut any := []load.Cond{}
				for item in v.as_list() {
					any << load.and(...gadget_where(item.as_map())!)
				}
				conds << load.or(...any)
			}
			'createdAt' { conds << load.eq('Stamps.created_at', gql_time(v)!) }
			'createdAtNEQ' { conds << load.ne('Stamps.created_at', gql_time(v)!) }
			'createdAtIn' {
				conds << load.or(...gql_times(v)!.map(load.eq('Stamps.created_at', it)))
			}
			'createdAtNotIn' {
				conds << load.and(...gql_times(v)!.map(load.ne('Stamps.created_at', it)))
			}
			'createdAtGT' { conds << load.gt('Stamps.created_at', gql_time(v)!) }
			'createdAtGTE' { conds << load.ge('Stamps.created_at', gql_time(v)!) }
			'createdAtLT' { conds << load.lt('Stamps.created_at', gql_time(v)!) }
			'createdAtLTE' { conds << load.le('Stamps.created_at', gql_time(v)!) }
			'updatedAt' { conds << load.eq('Stamps.updated_at', gql_time(v)!) }
			'updatedAtNEQ' { conds << load.ne('Stamps.updated_at', gql_time(v)!) }
			'updatedAtIn' {
				conds << load.or(...gql_times(v)!.map(load.eq('Stamps.updated_at', it)))
			}
			'updatedAtNotIn' {
				conds << load.and(...gql_times(v)!.map(load.ne('Stamps.updated_at', it)))
			}
			'updatedAtGT' { conds << load.gt('Stamps.updated_at', gql_time(v)!) }
			'updatedAtGTE' { conds << load.ge('Stamps.updated_at', gql_time(v)!) }
			'updatedAtLT' { conds << load.lt('Stamps.updated_at', gql_time(v)!) }
			'updatedAtLTE' { conds << load.le('Stamps.updated_at', gql_time(v)!) }
