			'serialNoIn' { conds << load.in_strings('serial_no', gql_strings(v)) }
			'serialNoNotIn' { conds << load.not_in_strings('serial_no', gql_strings(v)) }
			'serialNoGT' { conds << load.gt('serial_no', v.as_string()) }
