// color_enum returns the value of `models.Color` a GraphQL enum value names.
fn color_enum(name string) !int {
	return match name {
		'RED' { int(models.Color.red) }
		'GREEN' { int(models.Color.green) }
		'BLUE' { int(models.Color.blue) }
		else { error('`${name}` is not a Color') }
	}
}

// color_enums returns the values of `models.Color` that a list of GraphQL enum values
// names.
fn color_enums(v graphql.Value) ![]int {
	mut out := []int{}
	for item in v.as_list() {
		out << color_enum(item.as_string())!
	}
	return out
}

// gadget_connection returns the page of `q` that a `GadgetConnection`'s arguments
// ask for, bounded by `size`, and how many rows `q` matches when `totalCount`
// is asked for.
fn gadget_connection(q GadgetQuery, info graphql.FieldInfo, size graphql.PageSize) !graphql.Connection {
	p := graphql.page_args(info.args, size)!
	orders := gadget_order(info.arg('orderBy'), true)!
	rows := q.graphql_paged(orders, p)!.all()!
	total := if info.selected('totalCount') { q.count()! } else { 0 }
	return gadget_page(q.graph, rows, orders, p, total)
}

// graphql_paged returns `q` in `orders`, which end with the key (reversed for
// `last`), past the cursors of `p`, and limited to one row past the page.
fn (q GadgetQuery) graphql_paged(orders []load.Order, p graphql.PageArgs) !GadgetQuery {
	types := orders.map(it.typ)
	nulls := load.nulls_largest(q.graph.client.conn)
	mut conds := q.query.conds.clone()
	if c := p.after {
		conds << load.keyset(orders, load.decode_cursor(c, types)!, true, nulls)!
	}
	if c := p.before {
		conds << load.keyset(orders, load.decode_cursor(c, types)!, false, nulls)!
	}
	backward := p.last != none
	mut next := q
	next.query = load.Query{
		...q.query
		conds:  conds
		order:  ''
		desc:   false
		orders: if backward { orders.map(load.Order{ ...it, desc: !it.desc }) } else { orders }
		limit:  if c := p.first {
			c + 1
		} else if c := p.last {
			c + 1
		} else {
			0
		}
		offset: 0
	}
	return next
}

// gadget_page returns `nodes`, read in `orders` (reversed for `last`) and one row
// past the page, as a connection.
fn gadget_page(g Graph, nodes []GadgetNode, orders []load.Order, p graphql.PageArgs, total int) !graphql.Connection {
	mut page := nodes.clone()
	mut has_next := false
	mut has_previous := false
	if count := p.first {
		if page.len > count {
			has_next = true
			page = page[..count].clone()
		}
	} else if count := p.last {
		if page.len > count {
			has_previous = true
			page = page[..count].clone()
		}
		page.reverse_in_place()
	}
	cursors := gadget_cursors(g, page.map(it.gadget), orders)!
	return graphql.connection(page.map(graphql.Source(it)), cursors, has_next, has_previous, total)
}

// gadget_cursors returns the cursors of `rows`: the values of their order
// columns, those of edges read in one query.
fn gadget_cursors(g Graph, rows []models.Gadget, orders []load.Order) ![]string {
	exprs := load.expr_values(g.client.conn, 'gadgets', 'id', .i64,
		rows.map(it.id.str()), orders)!
	mut out := []string{cap: rows.len}
	for row in rows {
		from_exprs := exprs[row.id.str()] or { []orm.Primitive{} }
		mut values := []orm.Primitive{cap: orders.len}
		for i, o in orders {
			values << if o.expr != '' {
				from_exprs[i] or { orm.Primitive(orm.Null{}) }
			} else {
				gadget_order_value(row, o.column)
			}
		}
		out << load.encode_cursor(values)
	}
	return out
}

// gadget_order_value returns a column of a `gadgets` row, for a cursor.
fn gadget_order_value(row models.Gadget, column string) orm.Primitive {
	return match column {
		'Stamps.created_at' { orm.Primitive(row.created_at) }
